      ["What does tag kis mean?",["yesterday","today","tonight","tomorrow"],3,"tag kis is tomorrow; nag hmo is yesterday and hnub no is today."],
      ["What is kaum ob hlis ntuj?",["December","February","October","twelve days"],0,"Months are numbered: twelve + hlis ntuj is December."]
